        materyal: g('BTG Destekleyici Materyal'), guncellik: g('BTG Veri Güncelliği'),
        kaynak_notu: g('BTG Özel Kaynak / Belge İsteği', 'Yok')
      },
      ikiz: {
        kaynak: g('İkiz: Kaynak Soru / DNA', 'KAYNAK SORU YAPIŞTIRILMADI'),
        baglam: g('İkiz: Bağlam Değişim Düzeyi'), dna: g('İkiz: Matematiksel Yapı')
      },
      ek_istek: g('Ek İstek', 'Yok')
    },
    tymm2026: { ogrenim_becerisi: makeSkill(outcome), surec_bilesenleri: processComponents(outcome) },
    rotasyon: { son_100_baglam_ailesi: son100, son_200_aile_dna: son200dna, son_15_gorsel_ailesi: son15gorsel },
    revizyon_turu: 0
  }
}];

// 03R - GEÇERSİZ GİRDİ: kazanım/mikro zinciri eksik -> üretim yok
return [{ json: {
  baslik: 'MÜFREDAT VERİSİ EKSİK — FINAL KİLİDİ KAPALI',
  mesaj: $json.hata_mesaji,
  kural: 'V21 KAZANIM–ALT KONU TAMLIK KİLİDİ: veritabanında kazanım veya mikro eksikse soru uydurulmaz.'
}}];

// ================================================================
// 11 - KADEMELİ ÖN DENETİM (V22.4)
// Yalnız üretimi teknik olarak kullanılamaz yapan hatalar RED olur.
// Pedagojik/estetik/rotasyon/IQ sorunları UYARI olarak sonraki
// OTOPSİ ve YAYIN KURULU aşamalarına aktarılır.
// ================================================================
const ctx = $('04 - MASTER PROMPT Derleyici').first().json;
const execKey = String(ctx.execution_key || $execution.id || 'manual');
const runtime = $getWorkflowStaticData('global');
const revizyonTuru = Number(runtime.menar_revision_attempts?.[execKey] || 0);
const i = ctx.input || {};
const r = ctx.rotasyon || {};
const c = $json.output || $json;

const kritik = [];
const uyari = [];
const kelime = s => String(s || '').trim().split(/\s+/).filter(Boolean).length;
const sorular = Array.isArray(c.sorular) ? c.sorular : [];

// 1) Yalnız zorunlu teknik bütünlük RED üretir.
if (!sorular.length) kritik.push('SORU ÜRETİLMEDİ');

sorular.forEach((q, n) => {
  const no = n + 1;
  const secenekler = Array.isArray(q.secenekler) ? q.secenekler : [];
  const dogru = String(q.dogru_secenek || '').trim().toUpperCase();

  if (!String(q.kok || '').trim()) kritik.push(`SORU ${no}: soru kökü boş`);
  if (secenekler.length !== 5) kritik.push(`SORU ${no}: seçenek sayısı 5 değil`);
  if (!['A','B','C','D','E'].includes(dogru)) kritik.push(`SORU ${no}: doğru seçenek harfi geçersiz`);

  const norm = secenekler.map(x => String(x || '').trim().toLocaleLowerCase('tr-TR'));
  if (norm.length === 5 && new Set(norm).size !== 5)
    kritik.push(`SORU ${no}: tekrar eden seçenek var`);

  if (!String(q.dogru_cevap || '').trim())
    uyari.push(`SORU ${no}: doğru cevap açıklaması eksik`);
  if (!Array.isArray(q.cozum_adimlari) || !q.cozum_adimlari.length)
    uyari.push(`SORU ${no}: çözüm adımları eksik`);
  if (!String(q.ogrenme_becerisi || '').trim())
    uyari.push(`SORU ${no}: öğrenme becerisi eksik`);

  // 2) IQ artık ilk kapıda RED değildir; Solver/Yayın Kurulu doğrular.
  const iq = q.iq || {};
  const A=Number(iq.A||0), B=Number(iq.B||0), C=Number(iq.C||0);
  const D=Number(iq.D||0), E=Number(iq.E||0), F=Number(iq.F||0);
  const puan=A*40+B*15+C*20+D*25+E*15+F*30;
  const bantlar={
    IQ50:[40,79], IQ100:[80,119], IQ150:[120,189], IQ200:[190,249],
    IQ250:[250,299], IQ300:[300,384], IQ350:[385,99999]
  };
  q.iq_hesaplanan={A,B,C,D,E,F,puan,hedef:i.iq,bant:bantlar[i.iq]||null};
  const band=bantlar[i.iq];
  if (band && (puan < band[0] || puan > band[1]))
    uyari.push(`SORU ${no}: IQ puanı ${puan}, hedef ${band[0]}–${band[1]} dışında`);

  // 3) Dizgi sınırları ilk kapıda uyarıdır.
  const govde=kelime(q.kok);
  if (i.genislik === '85_MM' && govde > 120)
    uyari.push(`SORU ${no}: 85 mm için gövde uzun (${govde} kelime)`);
  if (i.genislik !== '85_MM' && govde > 220)
    uyari.push(`SORU ${no}: 185 mm için gövde uzun (${govde} kelime)`);

  const metin=[q.kok,...secenekler].join(' ');
  if (/\d+\.\d+/.test(metin)) uyari.push(`SORU ${no}: Türkçe ondalık ayırıcı kontrolü gerekli`);
  if (/(Ali|Ayşe|Ahmet|Mehmet)\b/.test(metin)) uyari.push(`SORU ${no}: klişe isim kullanımı`);
});

// 4) Manifest yalnız görsel gerekliyse teknik zorunluluktur.
const gorselKarari = String(i.gorsel_karari || i.gorselKarari || '').toLocaleUpperCase('tr-TR');
const gorselGerekli = gorselKarari.includes('ZORUNLU') || gorselKarari.includes('AI_OTOMATİK');
const man = c.gorsel_veri_manifesti || {};
if (gorselGerekli && !man.manifest_id)
  uyari.push('Görsel manifesti eksik; görsel aşamasından önce tamamlanmalı');

// 5) Bağlam/rotasyon sorunları üretimi başa döndürmez.
const aile=String(c.baglam_ailesi_kodu || c.baglam_ailesi_ad || '').trim();
if (!aile) uyari.push('Bağlam ailesi kodu eksik');
else {
  const norm=aile.toLocaleLowerCase('tr-TR');
  if ((r.son_100_baglam_ailesi || []).map(x=>String(x).toLocaleLowerCase('tr-TR')).includes(norm))
    uyari.push(`Bağlam ailesi son 100 üretimde kullanılmış: ${aile}`);
}

// 6) İstenen soru sayısı ile gelen sayı uyuşmuyorsa teknik RED.
const istenen = Number(i.soru_sayisi || i.soruSayisi || 1);
if (istenen > 0 && sorular.length !== istenen)
  kritik.push(`İstenen soru sayısı ${istenen}, üretilen ${sorular.length}`);

return [{json:{
  ...ctx,
  aday:c,
  on_denetim:{
    status: kritik.length ? 'RED' : 'PASS',
    kritik,
    red: kritik,
    uyari,
    kalite_durumu: uyari.length ? 'UYARILI_PASS' : 'TEMİZ_PASS'
  },
  execution_key:execKey,
  revizyon_turu:revizyonTuru
}}];

