parameters.jsCode:
// 20R - SOLVER A sonucunu taşıyıcıya yaz
const ctx = $('11 - Deterministik Ön Denetim').last().json;
return [{ json: { ...ctx, solver_a: $json.output || $json } }];

// ================================================================
// 22 - /OTOPSİ/ : A–E SEÇENEK OTOPSİSİ + SOLVER UYUŞMASI + MANİFEST ÇAPRAZ DENETİMİ
// ================================================================
const ctx = $('20R - Solver A Kaydet').last().json;
const A = ctx.solver_a || {};
const B = $json.output || $json;
const c = ctx.aday || {};
const sorular = c.sorular || [];
const man = c.gorsel_veri_manifesti || {};

const red = [];
const otopsi = [];

sorular.forEach((q, n) => {
  const a = (A.cozumler || [])[n] || {};
  const b = (B.cozumler || [])[n] || {};
  const key = String(q.dogru_secenek || '').trim();

  // --- SOLVER UYUŞMASI ---
  const uyus = a.dogru_secenek === b.dogru_secenek && String(a.sonuc).trim() === String(b.sonuc).trim();
  if (!uyus) red.push('SORU ' + (n + 1) + ': SOLVER A (' + a.dogru_secenek + '/' + a.sonuc + ') ile SOLVER B (' + b.dogru_secenek + '/' + b.sonuc + ') uyuşmuyor — RED');
  if (a.dogru_secenek !== key) red.push('SORU ' + (n + 1) + ': cevap anahtarı (' + key + ') Solver A ile uyuşmuyor (' + a.dogru_secenek + ')');

  // --- A–E SEÇENEK OTOPSİSİ ---
  const kayit = ['A', 'B', 'C', 'D', 'E'].map((h, k) => {
    const secA = (a.secenek_denetimi || []).find(x => x.harf === h) || {};
    const secB = (b.secenek_denetimi || []).find(x => x.harf === h) || {};
    let karar = 'YANLIŞ';
    if (secA.karar === 'DOĞRU' || secB.karar === 'DOĞRU') karar = 'DOĞRU';
    if (secA.karar === 'BELİRSİZ' || secB.karar === 'BELİRSİZ' || (secA.karar && secB.karar && secA.karar !== secB.karar)) karar = 'BELİRSİZ';
    return {
      harf: h,
      deger: (q.secenekler || [])[k],
      hata_yolu: (q.celdirici_hata_yollari || [])[k] || (h === key ? 'DOĞRU CEVAP' : 'BELİRTİLMEDİ'),
      kosullari_saglar: secA.kosullari_saglar ?? null,
      karar
    };
  });
  const dogruSayisi = kayit.filter(x => x.karar === 'DOĞRU').length;
  const belirsiz = kayit.filter(x => x.karar === 'BELİRSİZ');
  if (dogruSayisi !== 1) red.push('SORU ' + (n + 1) + ': TEK_DOĞRU RED — doğru işaretlenen seçenek sayısı ' + dogruSayisi);
  if (belirsiz.length) red.push('SORU ' + (n + 1) + ': BELİRSİZ seçenek(ler) ' + belirsiz.map(x => x.harf).join(',') + ' — FINAL KİLİDİ KAPALI');
  otopsi.push({ soru_no: n + 1, secenekler: kayit, solver_a: a, solver_b: b, solver_uyusmasi: uyus ? 'PASS' : 'RED' });
});

// --- MANİFEST ÇAPRAZ DENETİMİ: metindeki sayılar manifestte var mı ---
const sayiCek = s => (String(s || '').match(/-?\d+(?:[.,]\d+)?/g) || []).map(x => x.replace(',', '.'));
const manSayilar = new Set([
  ...(man.kullanilan_sayilar || []).map(x => String(x).replace(',', '.')),
  ...(man.secenek_degerleri || []).map(x => String(x).replace(',', '.')),
  ...sayiCek(man.dogru_cevap_degeri),
  ...((man.tablo?.rows || []).flat().flatMap(sayiCek))
]);
const metinSayilari = new Set(sorular.flatMap(q => sayiCek(q.kok).concat((q.secenekler || []).flatMap(sayiCek))));
const kacak = [...metinSayilari].filter(x => !manSayilar.has(x) && Math.abs(Number(x)) > 1);
if (kacak.length) red.push('MANİFEST ÇAPRAZ RED — metinde manifestte olmayan sayı(lar): ' + kacak.join(', '));

return [{ json: {
  ...ctx,
  solver_b: B,
  otopsi,
  otopsi_denetimi: { status: red.length ? 'RED' : 'PASS', red }
}}];

