parameters.jsCode:
// ================================================================
// 24 - ZORUNLU KANIT TABLOSU + PUANLAMA MATRİSİ + FINAL KİLİDİ
// Sahte PASS yasağı: fiilen çalışmamış denetim DOĞRULANAMADI yazılır.
// ================================================================
const ctx = $('22 - OTOPSİ: A–E Seçenek + Manifest Çapraz').last().json;
const kurul = $json.output || $json;
const i = ctx.input;
const c = ctx.aday || {};

const on = ctx.on_denetim || {};
const ot = ctx.otopsi_denetimi || {};
const tumRed = [...new Set([...(on.red || []), ...(ot.red || []), ...(kurul.red_nedenleri || [])].filter(Boolean))];

// --- PUANLAMA MATRİSİ (10 üzerinden) ---
const p = kurul.puanlama || {};
const puanHam = [
  ['kazanim_uyumu', 1.5], ['matematiksel_dogruluk', 2], ['gorsel_islevsellik', 1.5],
  ['bilgi_tekrarsizligi', 1], ['celdirici_kalitesi', 1.5], ['iq_uygunlugu', 1],
  ['baglam_islevselligi', 1], ['dil_yayin_duzeni', 0.5]
].reduce((s, [k, max]) => s + Math.min(Math.max(Number(p[k] || 0), 0), max), 0);
const puan = Math.round(puanHam * 10) / 10;

const gorselGerekli = (c.baglam_katmani || {}).gerekli || (c.veri_katmani || {}).gerekli;
const T = {
  'KAZANIM / MİKRO': kurul.kazanim_uyumu || 'DOĞRULANAMADI',
  'MANİFEST': (ot.red || []).some(x => x.includes('MANİFEST')) ? 'RED' : 'PASS',
  'SOLVER A SONUCU': (ctx.solver_a?.cozumler || []).map(x => x.dogru_secenek + ':' + x.sonuc).join(' | ') || 'DOĞRULANAMADI',
  'SOLVER B SONUCU': (ctx.solver_b?.cozumler || []).map(x => x.dogru_secenek + ':' + x.sonuc).join(' | ') || 'DOĞRULANAMADI',
  'SOLVER UYUŞMASI': (ctx.otopsi || []).every(x => x.solver_uyusmasi === 'PASS') ? 'PASS' : 'RED',
  'TEK DOĞRU / PUANLANABİLİRLİK': (ot.red || []).some(x => x.includes('TEK_DOĞRU') || x.includes('BELİRSİZ')) ? 'RED' : 'PASS',
  'IQ GERÇEK SEVİYE': (c.sorular || []).map(q => (q.iq_hesaplanan || {}).puan).join(' | '),
  'IQ UYUMU': (on.red || []).some(x => x.includes('IQ')) ? 'RED' : 'PASS',
  'BAĞLAM ROTASYONU': (on.red || []).some(x => x.includes('ROTASYON')) ? 'RED' : 'PASS',
  'KUTU TAŞMA': (on.red || []).some(x => x.includes('KUTU TAŞMA')) ? 'RED' : 'PASS',
  'TYMM UYUMU': kurul.tymm_uyumu || 'DOĞRULANAMADI',
  'DERS HAKEMİ': kurul.ders_hakemi || 'DOĞRULANAMADI',
  'ÖLÇME UZMANI': kurul.olcme_uzmani || 'DOĞRULANAMADI',
  'GÖRSEL / PNG': gorselGerekli ? 'AŞAMA 2 BEKLİYOR' : 'UYGULANMAZ',
  'BUILDER / IDML MANİFESTİ': ['MENAR_BUILDER_JSON', 'IDML_PAKET', 'INDD_PAKET', 'INDD_RAW_PRO'].includes(i.cikti) ? 'PASS' : 'UYGULANMAZ',
  'YAYIN PUANI': puan.toFixed(1) + '/10',
  'BAŞ EDİTÖR': kurul.bas_editor || 'DOĞRULANAMADI',
  'YAYIN KURULU': kurul.yayin_kurulu || 'DOĞRULANAMADI'
};

// V22.5: FINAL kapısı yalnız gerçekten kritik ve kanıtlanmış hatalarda kapanır.
// Puan düşüklüğü, DOĞRULANAMADI veya editoryal uyarılar yeniden üretim döngüsü başlatmaz.
const kritikRed = tumRed.filter(x => {
  const s = String(x || '').toLocaleUpperCase('tr-TR');
  return s.includes('SORU ÜRETİLMEDİ')
    || s.includes('SORU KÖKÜ BOŞ')
    || s.includes('SEÇENEK SAYISI')
    || s.includes('DOĞRU SEÇENEK HARFİ GEÇERSİZ')
    || s.includes('TEKRAR EDEN SEÇENEK')
    || s.includes('SOLVER UYUŞMAZ')
    || s.includes('TEK_DOĞRU')
    || s.includes('BELİRSİZ DOĞRU')
    || s.includes('MATEMATİKSEL HATA');
});
const kapali = kritikRed.length > 0;
T['FINAL KİLİDİ'] = kapali ? 'KAPALI' : (puan < 8.0 || tumRed.length ? 'UYARILI_AÇIK' : 'AÇIK');

const kanit_tablosu = Object.entries(T).map(([k, v]) => k + '=[' + v + ']').join('\n');
const denetim_satiri = 'Kazanım ' + T['KAZANIM / MİKRO'] + ' · Matematik ' + T['SOLVER UYUŞMASI']
  + ' · Tek Doğru ' + T['TEK DOĞRU / PUANLANABİLİRLİK'] + ' · IQ ' + T['IQ UYUMU']
  + ' · Bağlam ' + T['BAĞLAM ROTASYONU'] + ' · Taşma ' + T['KUTU TAŞMA']
  + ' · TYMM ' + T['TYMM UYUMU'] + ' · Puan ' + puan.toFixed(1).replace('.', ',') + '/10'
  + ' · Final Kilidi ' + T['FINAL KİLİDİ'];

return [{ json: {
  ...ctx, yayin_kurulu: kurul,
  kanit_tablosu, denetim_satiri, yayin_puani: puan,
  final_kilidi: T['FINAL KİLİDİ'], red_nedenleri: tumRed, kritik_red_nedenleri: kritikRed, yayin_uyarilari: [...new Set([...(ctx.on_denetim?.uyari || []), ...tumRed])]
}}];

// ================================================================
// 26 - YALNIZ YAPISAL HATA ONARIMI (V22.5)
// Yalnız 11/12 kapısındaki teknik RED alanlarını onarır.
// En fazla iki yeniden üretim yapılır; kalite uyarıları sonraki
// Solver ve Yayın Kurulu aşamalarına bırakılır.
// ================================================================
const j=$json;
const base=$('04 - MASTER PROMPT Derleyici').first().json;
const execKey=String(j.execution_key || base.execution_key || $execution.id || 'manual');
const runtime=$getWorkflowStaticData('global');
runtime.menar_revision_attempts=runtime.menar_revision_attempts || {};
const tur=Number(runtime.menar_revision_attempts[execKey] || 0)+1;
runtime.menar_revision_attempts[execKey]=tur;

const red=[...new Set([
  ...(j.on_denetim?.kritik || j.on_denetim?.red || []),
  ...(j.red_nedenleri || []),
  ...(j.otopsi_denetimi?.red || []),
  ...(j.yayin_kurulu?.red_nedenleri || [])
].map(x=>String(x||'').trim()).filter(Boolean))];
if (!red.length) red.push('Çıktının zorunlu JSON alanlarını ve soru bütünlüğünü düzelt.');

const aday=j.aday || {};
const compactInput={
  mode:base.input?.mode,
  sinif:base.input?.sinif,
  tema:base.input?.tema,
  kod:base.input?.kod,
  kazanim:base.input?.kazanim,
  mikro:base.input?.mikro,
  iq:base.input?.iq,
  soru_sayisi:base.input?.soru_sayisi,
  genislik:base.input?.genislik,
  cikti:base.input?.cikti,
  gorsel_karari:base.input?.gorsel_karari
};

const prompt=[
  'MENAR MATEMATİK — KRİTİK JSON ONARIMI',
  'Bu bir yeniden tasarım görevi değildir.',
  'Mevcut adayın matematiksel çekirdeğini, kazanımını ve doğru cevabını mümkün olduğunca koru.',
  'Yalnız aşağıdaki teknik hataları düzelt.',
  'Tam ve geçerli JSON dışında hiçbir şey yazma.',
  '',
  'GİRDİ:', JSON.stringify(compactInput),
  '',
  'KRİTİK HATALAR:', ...red.map((x,k)=>`${k+1}. ${x}`),
  '',
  'MEVCUT ADAY:', JSON.stringify(aday)
].join('\n');

return [{json:{
  ...base,
  master_prompt:prompt,
  execution_key:execKey,
  revizyon_turu:tur,
  onceki_aday:aday,
  son_red_nedenleri:red
}}];

// 28 - ÜÇ KONTROLLÜ REVİZYON SONRASI DURDUR
const j = $json;
const execKey = String(j.execution_key || $execution.id || 'manual');
const runtime = $getWorkflowStaticData('global');
const tamamlanan = Math.max(0, Number(runtime.menar_revision_attempts?.[execKey] || j.revizyon_turu || 0) - 1);
const sik = {};
const nedenler = [...new Set([
  ...(j.red_nedenleri || []), ...(j.on_denetim?.red || []),
  ...(j.otopsi_denetimi?.red || []), ...(j.yayin_kurulu?.red_nedenleri || [])
].filter(Boolean))];
nedenler.forEach(x => { const k = String(x).split('—')[0].split(':')[0].trim(); sik[k] = (sik[k] || 0) + 1; });
const enSik = Object.entries(sik).sort((a, b) => b[1] - a[1])[0];
if (runtime.menar_revision_attempts) delete runtime.menar_revision_attempts[execKey];
if (runtime.menar_image_requests) delete runtime.menar_image_requests[execKey];
return [{ json: {
  baslik: 'ÜRETİM DURDURULDU — ' + tamamlanan + ' KONTROLLÜ REVİZYON TAMAMLANDI',
  surekli_red_veren: enSik ? enSik[0] : 'FINAL KİLİDİ',
  en_yakin_puan: Number(j.yayin_puani || 0).toFixed(1) + '/10',
  onerilen_tek_degisiklik: j.yayin_kurulu?.onerilen_degisiklik
    || 'En sık RED veren denetimin koşulunu veya hedef IQ/mikro kapsamını gözden geçirin.',
  kanit_tablosu: j.kanit_tablosu || '',
  red_nedenleri: nedenler,
  revizyon_sayisi: tamamlanan
}}];

