parameters.jsCode:
// ================================================================
// 30 - ROTASYON DEFTERİ (kalıcı): bağlam ailesi / çözüm DNA / görsel ailesi kaydı
// MASTER_CORE "kalıcı son-30 rotasyon" kuralının gerçek uygulaması budur.
// ================================================================
const j = $json;
const execKey = String(j.execution_key || $execution.id || 'manual');
const runtimeState = $getWorkflowStaticData('global');
if (runtimeState.menar_revision_attempts) delete runtimeState.menar_revision_attempts[execKey];
const c = j.aday || {};
const store = $getWorkflowStaticData('global');
store.rotation = Array.isArray(store.rotation) ? store.rotation : [];
store.rotation.push({
  ts: new Date().toISOString(),
  kod: j.input.kod, mikro: j.input.micro, mod: j.input.mode, iq: j.input.iq,
  baglam_ailesi: c.baglam_ailesi_kodu || c.baglam_ailesi_ad || '',
  cozum_dna: c.cozum_dna_kodu || '',
  gorsel_ailesi: (c.baglam_katmani || {}).gorsel_ailesi || '',
  puan: j.yayin_puani
});
if (store.rotation.length > 400) store.rotation = store.rotation.slice(-400);

const stamp = new Date().toISOString().replace(/[-:T]/g, '').slice(0, 14);
const soru_id = 'MENAR-' + j.input.kod.replace(/\./g, '') + '-' + stamp;

return [{ json: { ...j, soru_id, uretim_tarihi: new Date().toISOString().slice(0, 10),
  gorunmez_kunye: {
    soru_id, kazanim_kodu: j.input.kod, sinif_veya_sinav: j.input.sinif, alt_konu: j.input.micro,
    iq_kodu: j.input.iq, iq_gercek: (c.sorular || []).map(q => (q.iq_hesaplanan || {}).puan),
    baglam_ailesi: c.baglam_ailesi_kodu, puan: j.yayin_puani,
    uretim_tarihi: new Date().toISOString().slice(0, 10)
  }}}];

// ================================================================
// 41 - VERİ KATMANI: TABLO / GRAFİK SVG (deterministik, manifestten türetilir)
// Standalone + inline stil + Swis721 BT + Türkçe ondalık virgül
// ================================================================
const j = $json;
const c = j.aday || {};
const man = c.gorsel_veri_manifesti || {};
const vk = c.veri_katmani || {};
const W = j.input.genislik === '85_MM' ? 241 : 524; // pt cinsinden (85mm / 185mm)
const FONT = 'Swis721 BT, Arial, sans-serif';
const INK = '#111111', LINE = '#123E6B', SOFT = '#E8EDF3', ACC = '#B45309';
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const tr = v => String(v ?? '').replace(/(\d)\.(\d)/g, '$1,$2');

const assets = [];

// ---------------- TABLO ----------------
const tab = man.tablo || {};
if (vk.gerekli && (vk.tur === 'TABLO' || (tab.headers || []).length)) {
  const hs = tab.headers || [], rows = tab.rows || [];
  const cols = hs.length || (rows[0] || []).length;
  const cw = Math.floor((W - 2) / Math.max(cols, 1));
  const rh = 22, top = tab.caption ? 26 : 4;
  const H = top + rh * (rows.length + 1) + (tab.footnotes || []).length * 14 + 8;
  let s = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' + W + ' ' + H + '" width="' + W + '" height="' + H + '">';
  s += '<rect x="0" y="0" width="' + W + '" height="' + H + '" fill="#FFFFFF"/>';
  if (tab.caption) s += '<text x="1" y="16" style="font-family:' + FONT + ';font-size:9.5px;font-weight:bold;fill:' + INK + '">' + esc(tab.caption) + '</text>';
  s += '<rect x="1" y="' + top + '" width="' + (cw * cols) + '" height="' + rh + '" fill="' + SOFT + '"/>';
  hs.forEach((h, k) => {
    s += '<text x="' + (1 + cw * k + 6) + '" y="' + (top + 15) + '" style="font-family:' + FONT + ';font-size:8.5px;font-weight:bold;fill:' + INK + '">' + esc(h) + '</text>';
  });
  rows.forEach((row, ri) => {
    const y = top + rh * (ri + 1);
    row.forEach((cell, ci) => {
      s += '<text x="' + (1 + cw * ci + 6) + '" y="' + (y + 15) + '" style="font-family:' + FONT + ';font-size:8.5px;fill:' + INK + '">' + esc(tr(cell)) + '</text>';
    });
    s += '<line x1="1" y1="' + (y + rh) + '" x2="' + (1 + cw * cols) + '" y2="' + (y + rh) + '" style="stroke:' + LINE + ';stroke-width:0.5"/>';
  });
  for (let k = 0; k <= cols; k++)
    s += '<line x1="' + (1 + cw * k) + '" y1="' + top + '" x2="' + (1 + cw * k) + '" y2="' + (top + rh * (rows.length + 1)) + '" style="stroke:' + LINE + ';stroke-width:0.5"/>';
  s += '<rect x="1" y="' + top + '" width="' + (cw * cols) + '" height="' + (rh * (rows.length + 1)) + '" fill="none" style="stroke:' + LINE + ';stroke-width:1"/>';
  (tab.footnotes || []).forEach((fn, k) => {
    s += '<text x="1" y="' + (top + rh * (rows.length + 1) + 12 + k * 14) + '" style="font-family:' + FONT + ';font-size:7px;fill:#4B5563">' + esc(tr(fn)) + '</text>';
  });
  s += '</svg>';
  assets.push({ name: '06_Veri_Tablosu.svg', svg: s, tur: 'TABLO' });
}

// ---------------- ÇİZGİ / SÜTUN GRAFİĞİ ----------------
const seri = man.grafik_serisi || man.seri || null;
if (vk.gerekli && seri && Array.isArray(seri.noktalar) && seri.noktalar.length) {
  const H = 260, pad = { l: 46, r: 14, t: 22, b: 34 };
  const xs = seri.noktalar.map(p => Number(p.x)), ys = seri.noktalar.map(p => Number(p.y));
  const xmin = Math.min(...xs), xmax = Math.max(...xs);
  const ymin = Math.min(0, ...ys), ymax = Math.max(...ys);
  const px = v => pad.l + (W - pad.l - pad.r) * ((v - xmin) / ((xmax - xmin) || 1));
  const py = v => H - pad.b - (H - pad.t - pad.b) * ((v - ymin) / ((ymax - ymin) || 1));
  let s = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' + W + ' ' + H + '" width="' + W + '" height="' + H + '">';
  s += '<rect x="0" y="0" width="' + W + '" height="' + H + '" fill="#FFFFFF"/>';
  if (seri.baslik) s += '<text x="' + pad.l + '" y="14" style="font-family:' + FONT + ';font-size:9.5px;font-weight:bold;fill:' + INK + '">' + esc(seri.baslik) + '</text>';
  s += '<line x1="' + pad.l + '" y1="' + (H - pad.b) + '" x2="' + (W - pad.r) + '" y2="' + (H - pad.b) + '" style="stroke:' + INK + ';stroke-width:1"/>';
  s += '<line x1="' + pad.l + '" y1="' + pad.t + '" x2="' + pad.l + '" y2="' + (H - pad.b) + '" style="stroke:' + INK + ';stroke-width:1"/>';
  for (let k = 0; k <= 4; k++) {
    const v = ymin + (ymax - ymin) * k / 4, y = py(v);
    s += '<line x1="' + pad.l + '" y1="' + y + '" x2="' + (W - pad.r) + '" y2="' + y + '" style="stroke:' + SOFT + ';stroke-width:0.5"/>';
    s += '<text x="' + (pad.l - 6) + '" y="' + (y + 3) + '" text-anchor="end" style="font-family:' + FONT + ';font-size:7.5px;fill:' + INK + '">' + tr(Math.round(v * 100) / 100) + '</text>';
  }
  if (String(seri.tur || 'CIZGI').toUpperCase() === 'SUTUN') {
    const bw = Math.max(6, (W - pad.l - pad.r) / (seri.noktalar.length * 1.8));
    seri.noktalar.forEach(p => {
      s += '<rect x="' + (px(p.x) - bw / 2) + '" y="' + py(p.y) + '" width="' + bw + '" height="' + (py(ymin) - py(p.y)) + '" fill="' + LINE + '"/>';
    });
  } else {
    s += '<polyline points="' + seri.noktalar.map(p => px(p.x) + ',' + py(p.y)).join(' ') + '" fill="none" style="stroke:' + LINE + ';stroke-width:1.6"/>';
    seri.noktalar.forEach(p => { s += '<circle cx="' + px(p.x) + '" cy="' + py(p.y) + '" r="2.4" fill="' + ACC + '"/>'; });
  }
  seri.noktalar.forEach(p => {
    s += '<text x="' + px(p.x) + '" y="' + (H - pad.b + 13) + '" text-anchor="middle" style="font-family:' + FONT + ';font-size:7.5px;fill:' + INK + '">' + esc(tr(p.etiket ?? p.x)) + '</text>';
  });
  if (seri.x_baslik) s += '<text x="' + ((W + pad.l) / 2) + '" y="' + (H - 4) + '" text-anchor="middle" style="font-family:' + FONT + ';font-size:8px;fill:' + INK + '">' + esc(seri.x_baslik) + '</text>';
  if (seri.y_baslik) s += '<text x="12" y="' + (H / 2) + '" transform="rotate(-90 12 ' + (H / 2) + ')" text-anchor="middle" style="font-family:' + FONT + ';font-size:8px;fill:' + INK + '">' + esc(seri.y_baslik) + '</text>';
  s += '</svg>';
  assets.push({ name: '07_Grafik.svg', svg: s, tur: 'GRAFİK' });
}

// ---------------- GEOMETRİ / FERAGAT NOTU ----------------
const geo = man.geometrik_noktalar_ve_koordinatlar || man.geometrik_noktalar || null;
if (vk.gerekli && Array.isArray(geo) && geo.length >= 3) {
  const H = 240, pad = 26;
  const xs = geo.map(p => Number(p.x)), ys = geo.map(p => Number(p.y));
  const sx = (W - 2 * pad) / ((Math.max(...xs) - Math.min(...xs)) || 1);
  const sy = (H - 2 * pad) / ((Math.max(...ys) - Math.min(...ys)) || 1);
  const sc = Math.min(sx, sy);
  const PX = v => pad + (v - Math.min(...xs)) * sc;
  const PY = v => H - pad - (v - Math.min(...ys)) * sc;
  let s = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' + W + ' ' + H + '" width="' + W + '" height="' + H + '">';
  s += '<rect x="0" y="0" width="' + W + '" height="' + H + '" fill="#FFFFFF"/>';
  s += '<polygon points="' + geo.map(p => PX(p.x) + ',' + PY(p.y)).join(' ') + '" fill="none" style="stroke:' + LINE + ';stroke-width:1.6"/>';
  geo.forEach(p => {
    s += '<circle cx="' + PX(p.x) + '" cy="' + PY(p.y) + '" r="2.2" fill="' + INK + '"/>';
    s += '<text x="' + (PX(p.x) + 5) + '" y="' + (PY(p.y) - 5) + '" style="font-family:' + FONT + ';font-size:8.5px;fill:' + INK + '">' + esc(p.ad || '') + '</text>';
  });
  (man.veri_katmani_etiketleri || []).forEach((et, k) => {
    s += '<text x="' + (W - 4) + '" y="' + (16 + k * 12) + '" text-anchor="end" style="font-family:' + FONT + ';font-size:8px;fill:' + ACC + '">' + esc(tr(et)) + '</text>';
  });
  if (!man.olcekli_cizim)
    s += '<text x="' + (W - 4) + '" y="' + (H - 4) + '" text-anchor="end" style="font-family:' + FONT + ';font-size:6.5px;fill:#4B5563">Şekil temsili olup ölçekli çizilmemiştir.</text>';
  s += '</svg>';
  assets.push({ name: '08_Teknik_Cizim.svg', svg: s, tur: 'GEOMETRİ' });
}

const binary = {};
assets.forEach((a, k) => {
  binary['svg' + k] = {
    data: Buffer.from(a.svg, 'utf8').toString('base64'),
    mimeType: 'image/svg+xml', fileName: a.name, fileExtension: 'svg'
  };
});

return [{ json: { ...j, svg_assets: assets.map(a => ({ name: a.name, tur: a.tur })), svg_count: assets.length, gorsel_gerekli: !!(c.baglam_katmani || {}).gerekli && j.input.gorsel_karari !== 'GÖRSEL_YOK' }, binary }];

