// 51 - BAĞLAM GÖRSELİ İSTEK DURUMU (3D öncelik / MEB 2D uygunluk kilidi)
const ctx = $('41 - VERİ KATMANI: Tablo/Grafik SVG').last().json;
const p = $json.output || $json;
const bin = $input.first().binary || {};
const boyut = String(p.boyut || (ctx.aday?.baglam_katmani?.boyut) || '3D').toUpperCase();

const prompt = [
  p.prompt || '',
  '',
  'ZORUNLU KURALLAR (MENAR):',
  '- Görselde HİÇBİR yazı, rakam, harf, birim, etiket, logo, filigran veya ölçü bulunmayacak.',
  '- Beyaz veya çok açık düz zemin. Ders kitabı estetiği. En fazla 2–4 uyumlu renk.',
  '- Poster, afiş, dashboard, dekoratif ikon, QR, çerçeve, parlama, gölge, 3D gösteriş yok.',
  '- Yalnız sahneyi anlatır; sayısal veri taşımaz (veri katmanı ayrı SVG olarak dizilecektir).',
  boyut === '2D' ? '- MEB ders kitabı anlatımı: sade 2B teknik illüstrasyon.' : '- Temiz, gerçekçi 3B görselleştirme; süs değil, sahneyi tanıtır.'
].join('\n');

const requestState = {
  ...ctx,
  gorsel_prompt: prompt,
  gorsel_ailesi: p.gorsel_ailesi || ctx.aday?.baglam_katmani?.gorsel_ailesi || '',
  gorsel_boyut: boyut,
  gorsel_deneme: 1,
  image_model: 'gpt-image-1',
  image_size: ctx.input.genislik === '85_MM' ? '1024x1024' : '1536x1024',
  image_quality: 'high'
};
const execKey = String(ctx.execution_key || $execution.id || 'manual');
const runtime = $getWorkflowStaticData('global');
runtime.menar_image_requests = runtime.menar_image_requests || {};
runtime.menar_image_requests[execKey] = requestState;
return [{ json: requestState, binary: bin }];

// 53 - PNG BINARY + DOĞRULANMIŞ DATA URL OLUŞTUR
const base = $('41 - VERİ KATMANI: Tablo/Grafik SVG').last().json;
const execKey = String(base.execution_key || $execution.id || 'manual');
const runtime = $getWorkflowStaticData('global');
const ctx = runtime.menar_image_requests?.[execKey] || $('51 - Görsel İstek Durumu').last().json;
const res = $json;

let raw = res?.data?.[0]?.b64_json
  || res?.output?.find?.(o => o.type === 'image_generation_call')?.result
  || res?.data?.[0]?.image
  || null;

if (!raw || typeof raw !== 'string') {
  throw new Error('Görsel API yanıtında base64 görsel bulunamadı: ' + JSON.stringify(res).slice(0, 500));
}

// Data URL geldiyse yalnız base64 bölümünü al.
let b64 = raw.trim().replace(/^data:image\/(png|jpeg|jpg|webp|gif);base64,/i, '');
b64 = b64.replace(/\s+/g, '');

// Base64 ve dosya imzasını doğrula.
let bytes;
try {
  bytes = Buffer.from(b64, 'base64');
} catch (e) {
  throw new Error('Görsel base64 çözülemedi: ' + e.message);
}
if (!bytes || bytes.length < 100) {
  throw new Error('Üretilen görsel verisi boş veya aşırı kısa. Byte: ' + (bytes?.length || 0));
}

const isPng = bytes.length >= 8
  && bytes[0] === 0x89 && bytes[1] === 0x50 && bytes[2] === 0x4E && bytes[3] === 0x47
  && bytes[4] === 0x0D && bytes[5] === 0x0A && bytes[6] === 0x1A && bytes[7] === 0x0A;

if (!isPng) {
  const head = bytes.subarray(0, 16).toString('hex');
  throw new Error('Görsel PNG formatında değil. İlk byte imzası: ' + head);
}

const cleanB64 = bytes.toString('base64');
const fileName = '09_Baglam_Sahnesi.png';

return [{
  json: {
    ...ctx,
    context_image_filename: fileName,
    image_mime_type: 'image/png',
    image_byte_length: bytes.length,
    image_data_url: 'data:image/png;base64,' + cleanB64
  },
  binary: {
    png: {
      data: cleanB64,
      mimeType: 'image/png',
      fileName,
      fileExtension: 'png'
    }
  }
}];

