// 55 - RESPONSES API GÖRSEL DENETİM SONUCUNU BİRLEŞTİR
const ctx = $('53 - PNG Binary Oluştur').last().json;
const bin = $('53 - PNG Binary Oluştur').last().binary || {};
const res = $json;

let text = res?.output_text || null;
if (!text && Array.isArray(res?.output)) {
  for (const item of res.output) {
    if (!Array.isArray(item?.content)) continue;
    const part = item.content.find(c => c?.type === 'output_text' && typeof c?.text === 'string');
    if (part?.text) { text = part.text; break; }
  }
}

let v;
if (text && typeof text === 'string') {
  try { v = JSON.parse(text); }
  catch (e) {
    v = { status: 'DOĞRULANAMADI', yazi_var_mi: false, islev: '', nedenler: ['Denetim JSON ayrıştırılamadı: ' + text.slice(0, 300)] };
  }
} else if (res?.status && res?.nedenler) {
  v = res;
} else {
  v = { status: 'DOĞRULANAMADI', yazi_var_mi: false, islev: '', nedenler: ['Responses API içinde output_text bulunamadı.'] };
}

const status = String(v.status || 'DOĞRULANAMADI').toUpperCase();
return [{
  json: {
    ...ctx,
    // Büyük data URL sonraki node'lara taşınmasın.
    image_data_url: undefined,
    gorsel_denetimi: {
      status,
      nedenler: Array.isArray(v.nedenler) ? v.nedenler : [],
      yazi_var_mi: Boolean(v.yazi_var_mi),
      islev: v.islev ?? null
    },
    asama2_satiri: 'AŞAMA 2 (GÖRSEL-MANİFEST) DENETİMİ: ' + status + ' — ' + ((v.nedenler || []).join('; ') || 'manifest ile karşılaştırıldı')
  },
  binary: bin
}];

// 57 - GÖRSEL PROMPTUNU DÜZELT (en fazla 3 toplam deneme)
const j = $json;
const n = j.gorsel_denetimi?.nedenler || [];
const next = {
  ...j,
  gorsel_deneme: Number(j.gorsel_deneme || 1) + 1,
  gorsel_prompt: String(j.gorsel_prompt || '')
    + '\n\nÖNCEKİ DENEME RED ALDI. ZORUNLU DÜZELTMELER:\n- ' + n.join('\n- ')
    + '\n- Görselde kesinlikle yazı, rakam, harf, etiket veya filigran olmayacak.'
};
const execKey = String(j.execution_key || $execution.id || 'manual');
const runtime = $getWorkflowStaticData('global');
runtime.menar_image_requests = runtime.menar_image_requests || {};
runtime.menar_image_requests[execKey] = next;
return [{ json: next, binary: $input.first().binary || {} }];

// 59 - GÖRSELSİZ DEVAM: bağlam görseli olmadan yayın paketine geç
const j = $json;
return [{ json: {
  ...j,
  context_image_filename: null,
  asama2_satiri: 'AŞAMA 2 (GÖRSEL-MANİFEST) DENETİMİ: UYGULANMAZ — bağlam görseli kullanılmadı'
}, binary: $input.first().binary || {} }];

// ================================================================
// 70 - /İNDD -RAW- PRO/ : MATEMATİK DİZGİ KATMANI + YAYIN METNİ
// <KESIR>pay;payda</KESIR> · <KOK>x</KOK> · <US>taban;us</US> · <ALT>taban;indis</ALT>
// Arial 8,5 pt gövde/seçenek · 10 pt başlık · 85/185 mm
// ================================================================
const j = $json;
const execKey = String(j.execution_key || $execution.id || 'manual');
const runtimeState = $getWorkflowStaticData('global');
if (runtimeState.menar_image_requests) delete runtimeState.menar_image_requests[execKey];
const c = j.aday || {};
const i = j.input;
const asciiIste = /ASCII/i.test(String(i.ek_istek || '')) && ['INDD_RAW_PRO', 'INDD_PAKET', 'IDML_PAKET'].includes(i.cikti);

function dizgi(s) {
  let t = String(s ?? '');
  t = t.replace(/√\s*\(([^)]+)\)/g, '<KOK>$1</KOK>').replace(/√\s*(\d+(?:[.,]\d+)?|[a-zA-Z])/g, '<KOK>$1</KOK>');
  t = t.replace(/(\d+)\s*∛\s*/g, '<KOK derece="3">$1</KOK>').replace(/∛\s*(\d+|[a-zA-Z])/g, '<KOK derece="3">$1</KOK>');
  t = t.replace(/\(([^()\/]{1,24})\)\s*\/\s*\(([^()\/]{1,24})\)/g, '<KESIR>$1;$2</KESIR>');
  t = t.replace(/(?<![\/\d])(\d+(?:[.,]\d+)?)\s*\/\s*(\d+(?:[.,]\d+)?)(?!\/)/g, '<KESIR>$1;$2</KESIR>');
  t = t.replace(/([a-zA-Z0-9\)])\^\{?(-?\d+|[a-zA-Z])\}?/g, '<US>$1;$2</US>');
  t = t.replace(/([a-zA-Z0-9])²/g, '<US>$1;2</US>').replace(/([a-zA-Z0-9])³/g, '<US>$1;3</US>');
  t = t.replace(/([a-zA-Z])_\{?(\w+)\}?/g, '<ALT>$1;$2</ALT>');
  t = t.replace(/(\d)\.(\d)/g, '$1,$2');            // Türkçe ondalık
  return t;
}
function ascii(s) {
  return asciiIste ? String(s).replace(/ç/g, 'c').replace(/ğ/g, 'g').replace(/ı/g, 'i').replace(/ö/g, 'o')
    .replace(/ş/g, 's').replace(/ü/g, 'u').replace(/Ç/g, 'C').replace(/Ğ/g, 'G').replace(/İ/g, 'I')
    .replace(/Ö/g, 'O').replace(/Ş/g, 'S').replace(/Ü/g, 'U') : String(s);
}
const P = s => ascii(dizgi(s));

const STIL = {
  kunye: '01_KOD_VE_CEVAP', lead: 'M001-soru (P)', blok: 'M011-Soru_cizim_ortalama',
  onerme: 'M008-soru I.II.III.', kok: 'M003-soru (B)', secenek: 'M007-soru tamblok'
};
const st = c.stimulus || {};
const sorular = c.sorular || [];
const harf = ['A', 'B', 'C', 'D', 'E'];

// --- ÖĞRENCİ AKIŞI ---
const ogrenci = [];
if (st.title) ogrenci.push([STIL.kunye, P(st.title)]);
(st.paragraphs || []).forEach(p => ogrenci.push([STIL.lead, P(p)]));
if (j.svg_count) (j.svg_assets || []).forEach(a => ogrenci.push([STIL.blok, '[YERLEŞTİR: ' + a.name + ' — ' + a.tur + ' katmanı]']));
if (j.context_image_filename) ogrenci.push([STIL.blok, '[YERLEŞTİR: ' + j.context_image_filename + ' — bağlam katmanı]']);
(st.notes || []).forEach(n => ogrenci.push([STIL.onerme, P(n)]));
sorular.forEach((q, n) => {
  ogrenci.push([STIL.kok, (n + 1) + '. ' + P(q.kok)]);
  (q.secenekler || []).forEach((o, k) => ogrenci.push([STIL.secenek, harf[k] + ') ' + P(o)]));
  if (q.ogrenme_becerisi) ogrenci.push([STIL.kunye, 'Öğrenme Becerisi: ' + P(q.ogrenme_becerisi)]);
