const raw = rows => rows.map(([s, t]) => '<' + s + '>\t' + t).join('\n');

return [{ json: {
  ...j,
  indd: {
    stil_grubu: 'SORU_STİLLERİ', stiller: STIL,
    dizgi: { govde_pt: 8.5, baslik_pt: 10, font: 'Arial', genislik: i.genislik, ascii: asciiIste },
    ogrenci_rows: ogrenci, ogretmen_rows: ogretmen,
    ogrenci_raw: raw(ogrenci), ogretmen_raw: raw(ogretmen)
  }
}, binary: $input.first().binary || {} }];

// ================================================================
// 71 - GERÇEK İNDD PAKETİ (V21 İNDD_GERÇEK_PAKET_KİLİDİ)
// ICML = InDesign'a doğrudan Yerleştir (File > Place) ile açılan gerçek biçim
// ================================================================
const j = $json;
const c = j.aday || {};
const i = j.input;
const d = j.indd;
const prev = $input.first().binary || {};
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const b64 = s => Buffer.from(s, 'utf8').toString('base64');

// ---------- ICML ----------
function icml(rows, title) {
  const styles = [...new Set(rows.map(r => r[0]))];
  let x = '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n';
  x += '<?aid style="50" type="snippet" readerVersion="6.0" featureSet="513" product="15.0(105)"?>\n';
  x += '<Document DOMVersion="15.0" Self="menar_' + Date.now() + '">\n';
  x += '<RootCharacterStyleGroup Self="u_rcsg"><CharacterStyle Self="CharacterStyle/$ID/[No character style]" Name="$ID/[No character style]"/></RootCharacterStyleGroup>\n';
  x += '<RootParagraphStyleGroup Self="u_rpsg">\n';
  x += '<ParagraphStyleGroup Self="psg_menar" Name="' + d.stil_grubu + '">\n';
  styles.forEach((s, k) => {
    const pt = s === '01_KOD_VE_CEVAP' ? 10 : 8.5;
    x += '<ParagraphStyle Self="ParagraphStyle/' + d.stil_grubu + '%3a' + esc(s) + '" Name="' + esc(s) + '" '
      + 'PointSize="' + pt + '" AppliedFont="Arial" SpaceBefore="0" SpaceAfter="2" Leading="' + (pt + 2.5) + '"/>\n';
  });
  x += '</ParagraphStyleGroup>\n</RootParagraphStyleGroup>\n';
  x += '<Story Self="story_menar" AppliedTOCStyle="n" TrackChanges="false" StoryTitle="' + esc(title) + '">\n';
  rows.forEach(([s, t]) => {
    x += '<ParagraphStyleRange AppliedParagraphStyle="ParagraphStyle/' + d.stil_grubu + '%3a' + esc(s) + '">'
      + '<CharacterStyleRange AppliedCharacterStyle="CharacterStyle/$ID/[No character style]">'
      + '<Content>' + esc(t) + '</Content><Br/></CharacterStyleRange></ParagraphStyleRange>\n';
  });
  x += '</Story>\n</Document>';
  return x;
}

// ---------- RTF ----------
function rtf(rows) {
  const enc = s => String(s).split('').map(ch => {
    const cc = ch.charCodeAt(0);
    return cc > 127 ? '\\u' + cc + '?' : (ch === '\\' ? '\\\\' : ch === '{' ? '\\{' : ch === '}' ? '\\}' : ch);
  }).join('');
  let r = '{\\rtf1\\ansi\\deff0{\\fonttbl{\\f0 Arial;}}\\fs17\n';
  rows.forEach(([s, t]) => {
    const fs = s === '01_KOD_VE_CEVAP' ? 20 : 17;
    r += '{\\fs' + fs + ' ' + enc(t) + '\\par}\n';
  });
  return r + '}';
}

const kunye = j.gorunmez_kunye || {};
const manifest = {
  menar_builder: 'MENAR_BUILDER_V1',
  soru_id: j.soru_id, kunye,
