  'A–E SEÇENEK OTOPSİSİ:',
  ...(j.otopsi || []).flatMap(o => ['SORU ' + o.soru_no,
    ...o.secenekler.map(s => '  ' + s.harf + ') ' + s.deger + '  | hata yolu: ' + s.hata_yolu + ' | karar: ' + s.karar)]),
  '', 'UYARILAR: ' + ((j.on_denetim?.uyari || []).join(' | ') || 'yok')
