const yerlesim = [
  'MENAR — İNDD YERLEŞİM NOTU', '='.repeat(40),
  'Şablon: soru_kaliplari_ysyf.indd (yayın kalıbı)',
  'Stil grubu: ' + d.stil_grubu,
  'Gövde/seçenek: Arial ' + d.dizgi.govde_pt + ' pt · Başlık: ' + d.dizgi.baslik_pt + ' pt',
  'Çıktı genişliği: ' + d.dizgi.genislik + (d.dizgi.genislik === '85_MM' ? ' (tek kolon)' : ' (tam blok)'),
  'ASCII dönüşümü: ' + (d.dizgi.ascii ? 'UYGULANDI' : 'UYGULANMADI — Türkçe karakterler korunur'), '',
  'ADIMLAR:',
