const files = [
  ['f01', '01_OGRENCI_RAW.txt', d.ogrenci_raw, 'text/plain'],
  ['f02', '02_OGRETMEN_RAW.txt', d.ogretmen_raw, 'text/plain'],
  ['f03', '03_OGRENCI.icml', icml(d.ogrenci_rows, 'MENAR Öğrenci'), 'application/xml'],
  ['f04', '04_OGRETMEN.icml', icml(d.ogretmen_rows, 'MENAR Öğretmen'), 'application/xml'],
  ['f05', '05_SORU.rtf', rtf(d.ogrenci_rows), 'application/rtf'],
  ['f10', '10_Veri_Manifesti.json', JSON.stringify(manifest, null, 2), 'application/json'],
